class Solution {ArrayList<ArrayList<Integer>>a,reverse;boolean[]seen;ArrayList<Integer>finish;void first(int u){seen[u]=true;for(int v:a.get(u))if(!seen[v])first(v);finish.add(u);}void second(int u,ArrayList<Integer>group){seen[u]=true;group.add(u);for(int v:reverse.get(u))if(!seen[v])second(v,group);}public int[][]solve(int n,int[][]edges){a=new ArrayList<>();reverse=new ArrayList<>();for(int i=0;i<n;i++){a.add(new ArrayList<>());reverse.add(new ArrayList<>());}for(int[]e:edges){a.get(e[0]).add(e[1]);reverse.get(e[1]).add(e[0]);}seen=new boolean[n];finish=new ArrayList<>();for(int u=0;u<n;u++)if(!seen[u])first(u);Arrays.fill(seen,false);ArrayList<ArrayList<Integer>>groups=new ArrayList<>();for(int i=finish.size()-1;i>=0;i--){int u=finish.get(i);if(!seen[u]){ArrayList<Integer>group=new ArrayList<>();second(u,group);Collections.sort(group);groups.add(group);}}groups.sort((x,y)->Integer.compare(x.get(0),y.get(0)));int[][]out=new int[groups.size()][];for(int i=0;i<out.length;i++)out[i]=groups.get(i).stream().mapToInt(Integer::intValue).toArray();return out;}}